import { parse } from 'query-string';

const queryString = parse(window.location.search);

export function parseQueryString(fromCache: boolean = false) {
    if (fromCache) {
        return queryString;
    }

    return parse(window.location.search);
}

export function removeQueryString() {
    const cleanUrl = window.location.href.substring(0, window.location.href.indexOf('?'));
    window.history.replaceState({}, document.title, cleanUrl);
}

export function getGameNameFromHostName() {
    if (location.host.includes('192.168')) {
        return 'tombola';
    }

    return location.pathname.split('/')[1];
}
